template.script:
// Lightbox para imágenes del mosaic
document.querySelectorAll('.sv-tile').forEach(function(tile){
  tile.addEventListener('click', function(){
    var img = this.querySelector('img');
    if(img){
      document.getElementById('sv-lb-img').src = img.src;
      document.getElementById('sv-lightbox').classList.add('active');
    }
  });
});
// Video modal
document.querySelectorAll('.sv-vid').forEach(function(v){
  v.addEventListener('click', function(){
    document.getElementById('sv-vframe').src = 'https://www.youtube.com/embed/' + this.getAttribute('data-vid') + '?autoplay=1&rel=0';
    document.getElementById('sv-video-lb').classList.add('active');
  });
});
// Smooth scroll
document.querySelectorAll('.sv-wrap a[href^="#"]').forEach(function(a){
  a.addEventListener('click', function(e){
    var t = document.querySelector(a.getAttribute('href'));
    if(t){ e.preventDefault(); t.scrollIntoView({behavior:'smooth',block:'start'}); }
  });
});

